function chemical(key){const smiles=SMILES[key];if(!smiles)return molecule(key);let id='chem'+(++chemCanvasCount);return `<div class="chem-card"><svg id="${id}" class="chem-svg" data-smiles="${esc(smiles)}" aria-label="${esc(key)} 구조식"></svg></div>`}
function renderChemical(){if(!window.SmilesDrawer||!SmilesDrawer.SvgDrawer)return;document.querySelectorAll('.chem-svg[data-smiles]').forEach(svg=>{try{const d=new SmilesDrawer.SvgDrawer({width:260,height:148,bondThickness:1.8,fontSizeLarge:15,fontSizeSmall:11});SmilesDrawer.parse(svg.dataset.smiles,tree=>{if(svg.isConnected)d.draw(tree,svg,'light',false)},err=>{svg.outerHTML='<div class="chem-error">구조식을 불러오지 못했습니다</div>'})}catch(err){console.warn('Chemical renderer',err)}})}
function molecule(key){const m= typeof key==='string'?M[key]:key;if(!m)return '<span>구조 데이터 없음</span>';const all=m.a;const minX=Math.min(...all.map(x=>x[1]))-30,minY=Math.min(...all.map(x=>x[2]))-35,maxX=Math.max(...all.map(x=>x[1]))+36,maxY=Math.max(...all.map(x=>x[2]))+37;let s=`<svg class="molecule" viewBox="${minX} ${minY} ${maxX-minX} ${maxY-minY}" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="분자 결합선 구조식">`;
for(const [i,j,o] of m.b){const a=all[i],b=all[j],dx=b[1]-a[1],dy=b[2]-a[2],l=Math.hypot(dx,dy)||1,ux=-dy/l*4,uy=dx/l*4;for(let k=0;k<o;k++){let off=(k-(o-1)/2)*2;s+=`<line x1="${a[1]+ux*off}" y1="${a[2]+uy*off}" x2="${b[1]+ux*off}" y2="${b[2]+uy*off}" stroke="#203248" stroke-width="2.7" stroke-linecap="round"/>`;}}
all.forEach(([el,x,y],i)=>{if(el!=='C'||m.charge?.[i]){s+=`<rect x="${x-14}" y="${y-14}" width="28" height="28" rx="5" fill="#eef4f8"/><text x="${x}" y="${y+5}" font-size="17" font-weight="bold" text-anchor="middle" fill="${el==='O'?'#d94e50':el==='Br'?'#8a5fa8':'#243c53'}">${esc(el)}${m.charge?.[i]||''}</text>`;}});return s+'</svg>'}
