const KEYS={history:'ocs_history_v1',wrong:'ocs_wrong_v1'};function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}function save(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{alert('저장에 실패했습니다. 브라우저 저장 공간을 확인하세요.')}}let state={page:'home',filter:'all',chapter:'all',level:'all',current:null,selected:null,checked:false,answerMode:'choice',typed:'',history:read(KEYS.history,[]),wrong:read(KEYS.wrong,[]),editor:{atoms:[],bonds:[],element:'C',order:1,selected:null},specTab:'ir'};
function nav(page){state.page=page;state.checked=false;state.selected=null;render();scrollTo(0,0)}function htmlShell(content){let navs=[['home','⌂','대시보드'],['practice','◈','문제 풀기'],['lessons','▤','개념 노트'],['wrong','↻','오답 노트'],['stats','▥','학습 통계']];$('#app').innerHTML=`<div class="mobilebar">${navs.map(([p,i,n])=>`<button class="btn small ${state.page===p?'primary':''}" data-nav="${p}">${i} ${n}</button>`).join('')}</div><div class="shell"><aside class="sidebar"><div class="logo">Organic<span>Lab.</span></div><div class="tagline">ORGANIC CHEMISTRY STUDIO</div>${navs.map(([p,i,n])=>`<button class="nav ${state.page===p?'active':''}" data-nav="${p}"><span>${i}</span>${n}</button>`).join('')}<div class="sidefoot tiny">대학 유기화학 · 개인 독학용<br>데이터는 현재 브라우저에 저장</div></aside><main class="main">${content}<div class="footnote" style="margin-top:36px">학습용 초기 버전 · 모든 예시는 일반화된 반응 조건을 전제로 합니다. 구체적인 기질·용매·온도에 따라 결과가 달라질 수 있습니다.</div></main></div>`;document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));queueMicrotask(renderChemical)}
function header(eyebrow,title,detail){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${detail}</p>`}
function home(){let done=new Set(state.history.map(x=>x.id)).size,correct=state.history.filter(x=>x.correct).length;htmlShell(header('study dashboard','오늘의 유기화학, 여기서 시작해요.','구조식을 읽고, 반응을 예측하고, 스펙트럼으로 미지 화합물을 찾아보세요.')+`<div class="cards"><div class="card"><div class="tiny">등록 문제</div><div class="metric">${Q.length+SPEC.length}</div><p>6개 유형 · 직접 제작한 예제</p></div><div class="card"><div class="tiny">풀이한 고유 문항</div><div class="metric">${done}</div><p>누적 시도 ${state.history.length}회</p></div><div class="card"><div class="tiny">누적 정답률</div><div class="metric">${state.history.length?Math.round(correct/state.history.length*100):0}%</div><p>모든 풀이 시도 기준</p></div></div><div class="panel"><div class="row spread"><div><h2>유형별 연습</h2><p class="muted">원하는 분야를 선택해 바로 문제를 풀어보세요.</p></div><button class="btn primary" id="allstart">전체 문제 풀기 →</button></div><div class="cards">${Object.entries(TYPES).map(([k,v])=>`<button class="listitem" data-type="${k}"><div class="pill mint" style="display:inline-block">${Q.filter(q=>q.type===k).length+SPEC.filter(q=>q.type===k).length}문항</div><h3 style="margin:15px 0 0">${v}</h3></button>`).join('')}</div></div><div class="panel"><h2>구현된 기능</h2><div class="muted">✓ SMILES 기반 전문 SVG 구조식　 ✓ 단계별 해설　 ✓ 선택형·시약 단답형　 ✓ IR·NMR 그림　 ✓ Kekule.js 전문 구조식 편집기(기본 편집기 예비 제공)　 ✓ 오답 저장 및 통계</div><p class="footnote">분광학에서는 Kekule.js 전문 구조식 편집기를 사용하며, 불러오지 못할 때 기본 편집기로 전환됩니다. 채점은 단순 비입체 원자·결합 그래프 비교만 지원합니다.</p></div>`);$('#allstart').onclick=()=>{state.filter='all';nav('practice')};document.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{state.filter=b.dataset.type;nav('practice')})}
function practice(){let pool=[...Q,...SPEC].filter(q=>(state.filter==='all'||q.type===state.filter)&&(state.chapter==='all'||q.chapter===state.chapter)&&(state.level==='all'||String(q.level)===state.level));let chapters=[...new Set([...Q,...SPEC].map(q=>q.chapter))];let list=`${header('practice mode','문제은행','유형·단원·난이도를 골라 문제를 풀어 보세요.')}<div class="panel"><div class="filterbar"><select class="field" id="typefilter"><option value="all">전체 유형</option>${Object.entries(TYPES).map(([k,v])=>`<option value="${k}" ${state.filter===k?'selected':''}>${v}</option>`).join('')}</select><select class="field" id="chapfilter"><option value="all">전체 단원</option>${chapters.map(c=>`<option ${state.chapter===c?'selected':''}>${c}</option>`).join('')}</select><select class="field" id="levelfilter"><option value="all">전체 난이도</option><option value="1" ${state.level==='1'?'selected':''}>기초</option><option value="2" ${state.level==='2'?'selected':''}>응용</option><option value="3" ${state.level==='3'?'selected':''}>고난도</option></select></div><div class="row spread"><span class="muted">총 ${pool.length}문항</span><button class="btn primary" id="random" ${pool.length?'':'disabled'}>무작위 한 문제 →</button></div></div><div class="panel"><h2>문항 목록</h2><div class="list">${pool.map(q=>`<button class="listitem" data-q="${q.id}"><div class="row spread"><span><b>${q.id}</b>　${esc(q.prompt)}</span><span class="pill">${q.level===1?'기초':q.level===2?'응용':'고난도'}</span></div><div class="tiny">${TYPES[q.type]} · ${q.chapter}</div></button>`).join('')||'<div class="empty">해당 필터의 문제가 없습니다.</div>'}</div></div>`;htmlShell(list);$('#typefilter').onchange=e=>{state.filter=e.target.value;practice()};$('#chapfilter').onchange=e=>{state.chapter=e.target.value;practice()};$('#levelfilter').onchange=e=>{state.level=e.target.value;practice()};$('#random').onclick=()=>openQ(pool[Math.floor(Math.random()*pool.length)].id);document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openQ(b.dataset.q))}
function openQ(id){state.current=id;state.selected=null;state.typed='';state.checked=false;state.answerMode='choice';state.editor={atoms:[],bonds:[],element:'C',order:1,selected:null};state.specTab='ir';state.page='question';render();scrollTo(0,0)}
function question(){let q=[...Q,...SPEC].find(x=>x.id===state.current);if(!q){nav('practice');return}let isS=q.type==='spectrum';let body=`${header(`practice / ${q.id}`,TYPES[q.type],esc(q.chapter)+' · '+(q.level===1?'기초':q.level===2?'응용':'고난도'))}<div class="panel"><div class="row spread"><span class="pill mint">${q.id}</span><button class="btn ghost small" id="back">← 문제 목록</button></div><div class="stem">${esc(q.prompt)}</div>`;
if(isS){body+=spectrumContent(q)}else{if(q.left||q.right){body+=`<div class="reaction">${q.left?chemical(q.left):''}${q.right?`<div class="rxarrow"><small>${esc(q.condition||'?')}</small>⟶</div>${chemical(q.right)}`:q.condition?`<div class="rxarrow"><small>${esc(q.condition)}</small>⟶ <b>?</b></div>`:''}</div>`}
if(q.type==='reagent'){body+=`<div class="row"><button class="btn small ${state.answerMode==='choice'?'primary':''}" data-mode="choice">선택형</button><button class="btn small ${state.answerMode==='text'?'primary':''}" data-mode="text">단답형</button></div>`}
if(state.answerMode==='text'){body+=`<input class="field" id="shortanswer" style="width:100%;margin:17px 0" placeholder="보기의 시약·조건 표현을 입력하세요" value="${esc(state.typed)}" ${state.checked?'disabled':''}/>`}else{body+=`<div class="options">${q.choices.map((c,i)=>{let value=Array.isArray(c)?c[0]:c;let cls=state.selected===i?'selected':'';if(state.checked&&i===q.correct)cls='correct';else if(state.checked&&i===state.selected&&i!==q.correct)cls='wrong';return `<button class="option ${cls}" data-opt="${i}" ${state.checked?'disabled':''}><span class="letter">${'ABCD'[i]}</span>${q.type==='product'?chemical(value)+`<span>${esc(c[1])}</span>`: `<span>${esc(Array.isArray(c)?`${value} — ${c[1]}`:value)}</span>`}</button>`}).join('')}</div>`}}
body+=`<div class="row spread"><button class="btn" id="next">다른 문제 ↻</button><button class="btn primary" id="check" ${state.checked?'disabled':''}>정답 확인</button></div><div id="result"></div></div>`;htmlShell(body);$('#back').onclick=()=>nav('practice');$('#next').onclick=()=>{let all=[...Q,...SPEC].filter(x=>x.id!==q.id);openQ(all[Math.floor(Math.random()*all.length)].id)};if(!isS){document.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{state.selected=Number(b.dataset.opt);document.querySelectorAll('[data-opt]').forEach(x=>x.classList.toggle('selected',x===b))});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{state.answerMode=b.dataset.mode;question()});if($('#shortanswer'))$('#shortanswer').oninput=e=>state.typed=e.target.value} else setupEditor(q);$('#check').onclick=()=>{try{checkAnswer(q)}catch(e){console.error(e)}}}
function normalize(t){return t.toLowerCase().replace(/[\s,_·.(){}\[\]⁺]/g,'').replaceAll('₄','4').replaceAll('₂','2').replaceAll('₃','3')}
function checkAnswer(q){if(state.checked)return;let correct=false;if(q.type==='spectrum'){if(!state.kekuleComposer&&!state.editor.atoms.length){alert('먼저 구조식을 그려 주세요.');return}correct=gradeSpectral(q);}else if(state.answerMode==='text'){if(!state.typed.trim()){alert('시약을 입력해 주세요.');return}correct=(q.accepted||[]).some(v=>normalize(v)===normalize(state.typed))}else{if(state.selected===null){alert('보기를 선택해 주세요.');return}correct=state.selected===q.correct}state.checked=true;state.history.push({id:q.id,type:q.type,correct,date:new Date().toISOString()});save(KEYS.history,state.history);if(correct){state.wrong=state.wrong.filter(x=>x!==q.id)}else if(!state.wrong.includes(q.id)){state.wrong.push(q.id)}save(KEYS.wrong,state.wrong);$('#check').disabled=true;const correctLabel=q.type==='spectrum'?q.expected:(q.type==='reagent'&&state.answerMode==='text'?(Array.isArray(q.choices[q.correct])?q.choices[q.correct][0]:q.choices[q.correct]):q.type==='product'?q.choices[q.correct][1]:q.choices[q.correct]);$('#result').innerHTML=`<div class="feedback ${correct?'':'bad'}"><strong>${correct?'✓ 정답입니다!':'✕ 다시 공부해 봅시다.'}</strong><div>정답: <b>${esc(correctLabel)}</b></div><div>${esc(q.explain)}</div>${q.type==='spectrum'?`<div style="background:#eef4f8;border-radius:10px;margin-top:12px;padding:12px;max-width:300px">${chemical(q.expected)}</div><div class="footnote">이 편집기는 결합 그래프를 비교하며 수소 수·전하·입체화학은 검증하지 않습니다. 시범판에서는 정답 구조의 원자와 결합을 정확히 배치해야 합니다.</div>`:''}</div>`}
function spectrumContent(q){return `<div class="split"><div><div class="row" style="margin-bottom:10px"><button class="btn small ${state.specTab==='ir'?'primary':''}" data-spec="ir">IR</button><button class="btn small ${state.specTab==='nmr'?'primary':''}" data-spec="nmr">¹H NMR</button></div><div id="spectrumpanel">${spectrumSVG(q)}</div><p class="footnote">교육용 모식 스펙트럼으로 실제 측정 원본이 아닙니다. 피크는 문제 설명에 맞게 단순화했습니다.</p><div class="panel"><b>분자식</b><p>${q.formula}</p><p class="muted">탄소의 생략 수소는 자동으로 고려하지 않으므로, 원자 사이 결합 그래프가 정답과 일치하도록 그리세요.</p></div></div><div><div class="editor"><div id="kekuleHost" class="kekule-host"></div><div id="fallbackEditor"><div class="toolbar" id="toolbar">${['C','O','N','Br','Cl'].map(a=>`<button class="tool ${a==='C'?'active':''}" data-atom="${a}">${a}</button>`).join('')}<button class="tool" id="bondOrder">결합: 단일</button><button class="tool" id="undo">되돌리기</button><button class="tool" id="clear">전체 지우기</button></div><svg id="editorSvg" class="editorsvg" viewBox="0 0 450 295" aria-label="화학 구조식 편집 캔버스"></svg><p class="hint">빈 공간 클릭: 선택 원자 추가 · 원자 두 개를 차례로 클릭: 결합 연결 · 같은 원자 재클릭: 선택 해제 · 결합 차수는 위 버튼에서 변경 (단일/이중/삼중).</p></div></div><p id="editorStatus" class="hint">전문 편집기 연결 중…</p></div></div></div>`}
function spectrumSVG(q){if(state.specTab==='nmr'){let bars=q.nmr.map(([ppm,n],i)=>{let x=36+(10-ppm)/10*390;return `<line x1="${x}" y1="175" x2="${x}" y2="${175-Math.min(118,n*18+20)}" stroke="#126f7c" stroke-width="3"/><text x="${x}" y="${160-Math.min(118,n*18+20)}" text-anchor="middle" fill="#16475a" font-size="12">${n}H</text>`}).join('');return `<div class="spectrum"><b>¹H NMR · δ(ppm)</b><svg viewBox="0 0 470 220"><path d="M35 175H432 M35 15V175" stroke="#354a60" fill="none"/>${bars}${[0,2,4,6,8,10].map(v=>`<text x="${36+(10-v)*39}" y="195" text-anchor="middle" font-size="12" fill="#364758">${v}</text>`).join('')}</svg></div>`}
let xFor=v=>35+(4000-v)/3500*395;let path='M35 35';for(let x=4000;x>=500;x-=10){let y=35;for(const [p,amp,w]of q.peaks){y+=amp*Math.exp(-Math.pow((x-p)/w,2))}path+=` L${xFor(x).toFixed(1)} ${Math.min(175,y).toFixed(1)}`;}return `<div class="spectrum"><b>IR · 파수 (cm⁻¹)</b><svg viewBox="0 0 470 220"><path d="M35 35V178H435" fill="none" stroke="#354a60"/><path d="${path}" fill="none" stroke="#126f7c" stroke-width="2"/>${[4000,3000,2000,1000,500].map(n=>`<text x="${xFor(n)}" y="198" font-size="12" text-anchor="middle" fill="#42576b">${n}</text>`).join('')}</svg></div>`}
// Minimal editor for acyclic skeletal graphs. Graph-isomorphism check ignores on-screen geometry.
function drawEditor(){const e=state.editor;let s=e.bonds.map(([i,j,o])=>{const a=e.atoms[i],b=e.atoms[j],dx=b.x-a.x,dy=b.y-a.y,len=Math.hypot(dx,dy)||1,px=-dy/len*4,py=dx/len*4;return Array.from({length:o},(_,k)=>{let p=k-(o-1)/2;return `<line x1="${a.x+px*p*2}" y1="${a.y+py*p*2}" x2="${b.x+px*p*2}" y2="${b.y+py*p*2}" stroke="#28455d" stroke-width="3"/>`}).join('')}).join('');s+=e.atoms.map((a,i)=>`<circle data-node="${i}" cx="${a.x}" cy="${a.y}" r="17" fill="${e.selected===i?'#99f0d5':'#e3f0f7'}" stroke="#305368" stroke-width="1.5"/><text data-node="${i}" x="${a.x}" y="${a.y+5}" text-anchor="middle" fill="#213647" font-size="15" font-weight="bold">${a.el}</text>`).join('');$('#editorSvg').innerHTML=s}
function setupEditor(q){document.querySelectorAll('[data-spec]').forEach(b=>b.onclick=()=>{state.specTab=b.dataset.spec;document.querySelectorAll('[data-spec]').forEach(z=>z.classList.toggle('primary',z===b));$('#spectrumpanel').innerHTML=spectrumSVG(q)});document.querySelectorAll('[data-atom]').forEach(b=>b.onclick=()=>{state.editor.element=b.dataset.atom;document.querySelectorAll('[data-atom]').forEach(x=>x.classList.toggle('active',x===b))});$('#bondOrder').onclick=()=>{state.editor.order=state.editor.order%3+1;$('#bondOrder').textContent='결합: '+['','단일','이중','삼중'][state.editor.order]};$('#clear').onclick=()=>{state.editor.atoms=[];state.editor.bonds=[];state.editor.selected=null;drawEditor()};$('#undo').onclick=()=>{if(state.editor.bonds.length)state.editor.bonds.pop();else state.editor.atoms.pop();state.editor.selected=null;drawEditor()};$('#editorSvg').onclick=ev=>{const e=state.editor;const node=ev.target.getAttribute('data-node');if(node!==null){let id=Number(node);if(e.selected===null)e.selected=id;else if(e.selected===id)e.selected=null;else{let bond=e.bonds.find(b=>(b[0]===e.selected&&b[1]===id)||(b[1]===e.selected&&b[0]===id));if(bond)bond[2]=e.order;else e.bonds.push([e.selected,id,e.order]);e.selected=null}}else{const svg=$('#editorSvg'),rect=svg.getBoundingClientRect(),x=(ev.clientX-rect.left)/rect.width*450,y=(ev.clientY-rect.top)/rect.height*295;let nearest=e.atoms.some(a=>Math.hypot(a.x-x,a.y-y)<34);if(!nearest){let idx=e.atoms.push({el:e.element,x,y})-1;if(e.selected!==null){e.bonds.push([e.selected,idx,e.order]);e.selected=null}else e.selected=idx}}drawEditor()};drawEditor();enableKekule()}
function molGraph(mol){let lines=mol.replace(/\r/g,'').split('\n');let idx=lines.findIndex(l=>/V2000/.test(l));if(idx<0)throw Error('V2000 형식만 지원');let counts=lines[idx];let n=parseInt(counts.slice(0,3)),b=parseInt(counts.slice(3,6));if(!n||n>50||!b)throw Error('원자나 결합이 없습니다');let atoms=lines.slice(idx+1,idx+1+n).map(l=>({el:l.slice(31,34).trim()}));let bonds=lines.slice(idx+1+n,idx+1+n+b).map(l=>[parseInt(l.slice(0,3))-1,parseInt(l.slice(3,6))-1,parseInt(l.slice(6,9))]);if(atoms.some(a=>!a.el)||bonds.some(x=>x.some(v=>Number.isNaN(v))))throw Error('구조 해석 실패');return {atoms,bonds}}
function gradeSpectral(q){if(!state.kekuleComposer)return isomorphic(state.editor,M[q.expected]);try{let obj=state.kekuleComposer.getChemObj();if(!obj){alert('먼저 구조식을 그려 주세요.');return false}let data=Kekule.IO.saveFormatData(obj,'mol');let g=molGraph(data);return isomorphic(g,M[q.expected])}catch(e){console.error(e);alert('구조식을 읽지 못했습니다. 결합을 완성하고 다시 시도해 주세요.');throw e}}
function enableKekule(){state.kekuleComposer=null;const status=$('#editorStatus'),host=$('#kekuleHost');if(!host)return;if(!window.Kekule||!Kekule.Editor?.Composer){status.textContent='편집기 CDN 연결 실패: 기본 편집기로 답안을 작성할 수 있습니다.';return}try{let cmp=new Kekule.Editor.Composer(host);cmp.setDimension('100%','360px');state.kekuleComposer=cmp;$('#fallbackEditor').style.display='none';status.textContent='Kekule.js 전문 편집기 · 구조를 그린 뒤 정답 확인을 누르세요. (결합/연결성 비교, 입체화학 채점 제외)'}catch(err){console.warn(err);status.textContent='전문 편집기 초기화에 실패하여 기본 편집기를 사용합니다.'}}
function isomorphic(editor,expected){let A=editor.atoms.map(a=>a.el),B=expected.a.map(a=>a[0]);if(A.length!==B.length||editor.bonds.length!==expected.b.length)return false;let n=A.length;if(n>12)return false;let adj=(b)=>{let x=Array.from({length:n},()=>Array(n).fill(0));b.forEach(([i,j,o])=>x[i][j]=x[j][i]=o);return x};let x=adj(editor.bonds),y=adj(expected.b),seen=new Set(),perm=Array(n).fill(-1);function rec(k){if(k===n)return true;for(let j=0;j<n;j++){if(seen.has(j)||A[k]!==B[j])continue;let ok=true;for(let i=0;i<k;i++)if(x[k][i]!==y[j][perm[i]]){ok=false;break}if(ok){seen.add(j);perm[k]=j;if(rec(k+1))return true;seen.delete(j)}}return false}return rec(0)}
function wrong(){let rows=state.wrong.map(id=>[...Q,...SPEC].find(q=>q.id===id)).filter(Boolean);htmlShell(header('review','오답 노트','틀린 문제는 자동으로 쌓이고, 다시 맞히면 목록에서 빠집니다.')+`<div class="panel"><div class="row spread"><h2>복습할 문제 ${rows.length}개</h2><button id="export" class="btn small">학습 기록 내보내기 ↓</button></div><div class="list">${rows.map(q=>`<button class="listitem" data-q="${q.id}"><b>${q.id}</b>　${esc(q.prompt)}<div class="tiny">${TYPES[q.type]}</div></button>`).join('')||'<div class="empty">아직 저장된 오답이 없습니다. 문제은행에서 연습을 시작해 보세요!</div>'}</div></div>`);document.querySelectorAll('[data-q]').forEach(b=>b.onclick=()=>openQ(b.dataset.q));$('#export').onclick=exportData}
function exportData(){const blob=new Blob([JSON.stringify({history:state.history,wrong:state.wrong},null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='organic-lab-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),500)}
function stats(){let h=state.history;htmlShell(header('my progress','학습 통계','문제 풀이 기록을 기반으로 취약한 유형을 확인하세요.')+`<div class="cards"><div class="card"><div class="tiny">총 시도</div><div class="metric">${h.length}</div></div><div class="card"><div class="tiny">고유 문항</div><div class="metric">${new Set(h.map(x=>x.id)).size}</div></div><div class="card"><div class="tiny">남은 오답</div><div class="metric">${state.wrong.length}</div></div></div><div class="panel"><h2>유형별 정답률</h2>${Object.entries(TYPES).map(([k,v])=>{let x=h.filter(y=>y.type===k),p=x.length?Math.round(100*x.filter(y=>y.correct).length/x.length):0;return `<div class="checkrow"><div class="row spread"><b>${v}</b><span class="tiny">${x.length}회 · ${p}%</span></div><div class="progress" style="margin-top:9px"><b style="width:${p}%"></b></div></div>`}).join('')}</div><div class="panel"><h2>데이터 관리</h2><p class="muted">학습 데이터는 이 기기의 브라우저에 저장됩니다. 다른 기기로 자동 동기화되지 않습니다.</p><div class="row"><button class="btn" id="export">JSON 내보내기</button><label class="btn" for="importfile">JSON 가져오기</label><input type="file" accept="application/json" id="importfile" hidden><button class="btn ghost" id="reset">기록 초기화</button></div></div>`);$('#export').onclick=exportData;$('#reset').onclick=()=>{if(confirm('모든 문제 풀이 기록과 오답 기록을 삭제할까요?')){state.history=[];state.wrong=[];save(KEYS.history,[]);save(KEYS.wrong,[]);stats()}};$('#importfile').onchange=async e=>{try{let d=JSON.parse(await e.target.files[0].text());if(!Array.isArray(d.history)||!Array.isArray(d.wrong))throw Error('잘못된 파일');state.history=d.history.filter(x=>typeof x.id==='string'&&typeof x.correct==='boolean');state.wrong=d.wrong.filter(x=>typeof x==='string');save(KEYS.history,state.history);save(KEYS.wrong,state.wrong);stats()}catch{alert('형식이 올바른 학습 기록 JSON 파일이 아닙니다.')}}}
const LESSONS=[{name:'친핵성 치환: SN1과 SN2',topic:'치환·제거',body:`<h3>SN2</h3><p>친핵체의 공격과 이탈기의 이탈이 동시에 일어나는 한 단계 반응입니다. 일반적인 속도식은 v=k[RX][Nu⁻]이며, 입체 중심에서 배치의 반전이 발생할 수 있습니다.</p><h3>SN1</h3><p>이탈기가 먼저 떨어져 카보양이온을 만드는 단계가 속도 결정 단계입니다. 카보양이온 안정도, 극성 양성자성 용매, 재배열 가능성을 고려해야 합니다.</p><h3>비교 기준</h3><ul><li>기질: 메틸·1차는 대체로 SN2에 유리하며, 3차는 일반적으로 SN2가 어렵습니다.</li><li>친핵체: 강한 친핵체는 SN2를 유리하게 만들 수 있습니다.</li><li>용매: 극성 비양성자성 용매는 일반적으로 SN2에 유리합니다.</li><li>경쟁 반응: 강염기·입체 장애·온도에 따라 E2 또는 E1이 우세할 수 있습니다.</li></ul>`},{name:'알켄의 첨가 반응',topic:'알켄',body:`<h3>산 촉매 수화</h3><p>알켄에 H와 OH가 첨가되어 알코올이 됩니다. 비대칭 알켄에서는 보다 안정한 카보양이온 형성이 위치선택성을 좌우할 수 있고, 재배열도 가능합니다.</p><h3>환원과 산화</h3><p>H₂와 금속 촉매를 이용한 수소화는 C=C를 C–C로 환원합니다. 오존 분해는 조건에 따라 이중 결합을 절단해 카보닐 화합물을 생성합니다.</p>`},{name:'IUPAC 명명법 기초',topic:'명명법',body:`<h3>기본 절차</h3><ol><li>최상위 작용기와 이를 포함하는 모체를 정합니다.</li><li>명명 규칙에 따라 번호를 부여합니다.</li><li>치환기의 위치와 이름을 접두사로 표시합니다.</li><li>결합 차수 및 작용기 접미사를 적용합니다.</li></ol><p>예: 2-methylbutane, propan-1-ol, propanone.</p>`},{name:'방향족 구조와 치환 위치',topic:'방향족',body:`<h3>o / m / p</h3><p>EAS 지향성: –OH, –OR, –R, 할로젠은 대체로 ortho/para 지향성이며 –NO₂, –CHO, –COOH 등은 meta 지향성입니다. 할로젠은 비활성화지만 ortho/para 지향성인 예외입니다.</p><h3>관용명</h3><p>Methylbenzene=toluene, hydroxybenzene=phenol, aminobenzene=aniline, benzenecarboxylic acid=benzoic acid.</p>`},{name:'IR과 NMR로 구조 추론하기',topic:'분광학',body:`<h3>IR</h3><p>결합의 진동에 대응하는 흡수대에서 작용기 정보를 얻습니다. O–H는 일반적으로 넓은 흡수, C=O는 강한 흡수 영역을 보입니다.</p><h3>¹H NMR</h3><p>화학적 이동, 적분, 다중선을 함께 해석합니다. 스펙트럼 하나로 단정하기보다 분자식 및 다른 스펙트럼과 교차 검증합니다.</p><p>이 버전의 스펙트럼 문제는 실제 실험값이 아닌 교육용 모식도입니다.</p>`}];
function lessons(){htmlShell(header('concept notes','개념 학습','문제에 등장하는 핵심 개념을 간단하게 정리했습니다. 계속 확장할 수 있는 구조입니다.')+`<div class="panel"><div class="list">${LESSONS.map((x,i)=>`<button class="listitem" data-lesson="${i}"><b>${x.name}</b><div class="tiny">${x.topic} · 요약 노트 →</div></button>`).join('')}</div></div>`);document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{state.lesson=+b.dataset.lesson;state.page='lesson';render()})}
function lesson(){let l=LESSONS[state.lesson]||LESSONS[0];htmlShell(header('concept notebook',l.name,'핵심 개념 요약')+`<div class="panel lesson">${l.body}<div class="row"><button class="btn primary" id="related">관련 문제 풀기 →</button><button class="btn" id="back">목록으로</button></div></div>`);$('#related').onclick=()=>{state.filter='all';state.chapter=l.topic;nav('practice')};$('#back').onclick=()=>nav('lessons')}
function render(){({home,practice,question,wrong,stats,lessons,lesson}[state.page]||home)()};render();
